// All 100 signature icons are generated — 320px WebP at /legacy/jutsu/<slug>.webp
// (docs/legacy-assets.md §3; slug = jutsu id minus the "legacy-" prefix), so the
// image path is set unconditionally. A jutsu added later without art would 404,
// but the combat/inspect UIs degrade gracefully (jutsu.image || shared || "").
// Regenerate any missing art with shinobij.client/scripts/gen-legacy-jutsu-icons.mjs.

// Tier caps ride on bloodlineRank, which normalizeJutsu deliberately drops
// (starters get theirs stamped at read time by markRank) — so re-stamp after
// normalizing, the same trailing-map pattern the bloodline data uses.
export const LEGACY_JUTSU_DEFS: LegacyJutsuDef[] = ROWS.map(({ legacyId, rank, j }) => {
    const jutsu: Jutsu = { ...normalizeJutsu(j), ...(rank ? { bloodlineRank: rank } : {}) };
    jutsu.image = `/legacy/jutsu/${jutsu.id.replace(/^legacy-/, "")}.webp`;
    return { legacyId, jutsu };
});

export const LEGACY_JUTSU_BY_ID: ReadonlyMap<string, Jutsu> = new Map(
    LEGACY_JUTSU_DEFS.map((d) => [d.jutsu.id, d.jutsu]),
);

export const LEGACY_JUTSU_ID_BY_LEGACY: ReadonlyMap<string, string> = new Map(
    LEGACY_JUTSU_DEFS.map((d) => [d.legacyId, d.jutsu.id]),
);

const DISCIPLINES = ["Taijutsu", "Bukijutsu", "Genjutsu", "Ninjutsu"] as const;

/**
 * Resolve a stored legacy jutsu for combat. Non-style DAMAGE signatures are
 * stored as type "Any" (the adaptive marker) because their Legacy can be earned
 * by any build — stamp the owner's trained specialty so the damage formula uses
 * the right offense composite on BOTH engines (server getOffense has no "Any"
 * branch and would silently scale them as Ninjutsu). 40-AP utilities stay "Any"
 * per the zero-damage convention; typed style signatures pass through untouched.
 * Mirrors the server's stamp in api/pvp/session.ts — KEEP IN SYNC.
 */
export function stampLegacyJutsuType(jutsu: Jutsu, specialty: string | undefined | null): Jutsu {
    if (jutsu.type !== "Any" || jutsu.ap !== 60) return jutsu;
    const sp = DISCIPLINES.includes(specialty as (typeof DISCIPLINES)[number])
        ? (specialty as (typeof DISCIPLINES)[number])
        : "Taijutsu";
    return { ...jutsu, type: sp };
}
